import AppKit
import Foundation
import Testing
@testable import MePaste

@MainActor
struct ClipboardPrivacyTests {
    @Test(arguments: [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType"
    ])
    func testPrivateMarkerSkipsWholeCopyIncludingUnmarkedItems(type: String) async throws {
        let pasteboard = NSPasteboard.withUniqueName()
        let monitor = ClipboardMonitor(pasteboard: pasteboard, frontmostApplicationIdentifier: { nil })
        defer { monitor.stop(); pasteboard.releaseGlobally() }
        var records: [ClipboardRecord] = []
        monitor.onNewRecord = { records.append($0) }
        monitor.start()
        let ordinary = NSPasteboardItem()
        ordinary.setString("first item", forType: .string)
        let privateItem = NSPasteboardItem()
        privateItem.setString("private item", forType: .string)
        privateItem.setData(Data(), forType: NSPasteboard.PasteboardType(type))
        pasteboard.clearContents()
        pasteboard.writeObjects([ordinary, privateItem])
        monitor.checkForChanges()
        try await Task.sleep(for: .milliseconds(30))
        #expect(records.isEmpty)
    }

    @Test func testExcludedCopyIsNotRecapturedAfterSwitchingApps() async throws {
        let pasteboard = NSPasteboard.withUniqueName()
        var applicationID = "com.example.private"
        let monitor = ClipboardMonitor(pasteboard: pasteboard, frontmostApplicationIdentifier: { applicationID })
        defer { monitor.stop(); pasteboard.releaseGlobally() }
        var records: [ClipboardRecord] = []
        monitor.onNewRecord = { records.append($0) }
        monitor.excludedApplicationBundleIdentifiers = [applicationID]
        monitor.start()
        pasteboard.clearContents()
        pasteboard.setString("excluded", forType: .string)
        monitor.checkForChanges()
        applicationID = "com.example.allowed"
        monitor.checkForChanges()
        try await Task.sleep(for: .milliseconds(30))
        #expect(records.isEmpty)
        pasteboard.clearContents()
        pasteboard.setString("allowed", forType: .string)
        monitor.checkForChanges()
        try await waitUntil { records.count == 1 }
        #expect(records.first?.plainText == "allowed")
    }

    @Test func testResumeDoesNotBackfillPausedCopiesEvenBeforeNextPoll() async throws {
        let pasteboard = NSPasteboard.withUniqueName()
        let monitor = ClipboardMonitor(pasteboard: pasteboard, frontmostApplicationIdentifier: { nil })
        defer { monitor.stop(); pasteboard.releaseGlobally() }
        var records: [ClipboardRecord] = []
        monitor.onNewRecord = { records.append($0) }
        monitor.start()
        monitor.isPaused = true
        pasteboard.clearContents()
        pasteboard.setString("private while paused", forType: .string)
        // Deliberately do not poll before resuming.
        monitor.isPaused = false
        monitor.checkForChanges()
        try await Task.sleep(for: .milliseconds(30))
        #expect(records.isEmpty)
        pasteboard.clearContents()
        pasteboard.setString("after resume", forType: .string)
        monitor.checkForChanges()
        try await waitUntil { records.count == 1 }
        #expect(records.first?.plainText == "after resume")
    }

    @Test func testPausedMonitorStillAllowsExplicitHistoryCopy() async throws {
        let pasteboard = NSPasteboard.withUniqueName()
        let monitor = ClipboardMonitor(pasteboard: pasteboard, frontmostApplicationIdentifier: { nil })
        defer { monitor.stop(); pasteboard.releaseGlobally() }
        var captures = 0
        monitor.onNewRecord = { _ in captures += 1 }
        monitor.start()
        monitor.isPaused = true
        pasteboard.clearContents()
        pasteboard.setString("not captured", forType: .string)
        monitor.checkForChanges()
        #expect(monitor.write(textRecord("explicit old item")))
        #expect(pasteboard.string(forType: .string) == "explicit old item")
        monitor.isPaused = false
        monitor.checkForChanges()
        try await Task.sleep(for: .milliseconds(30))
        #expect(captures == 0)
    }

    @Test(arguments: [true, false])
    func testPrivacyChangesDiscardInFlightCaptures(pause: Bool) async throws {
        let pasteboard = NSPasteboard.withUniqueName()
        let monitor = ClipboardMonitor(pasteboard: pasteboard, frontmostApplicationIdentifier: { "com.example.app" })
        defer { monitor.stop(); pasteboard.releaseGlobally() }
        var captures = 0
        monitor.onNewRecord = { _ in captures += 1 }
        monitor.start()
        pasteboard.clearContents()
        pasteboard.setString("pending", forType: .string)
        monitor.checkForChanges()
        if pause {
            monitor.isPaused = true
        } else {
            monitor.excludedApplicationBundleIdentifiers = ["com.example.app"]
        }
        try await Task.sleep(for: .milliseconds(30))
        #expect(captures == 0)
    }

    @Test func testRemovingExclusionDoesNotBackfillUnobservedClipboard() async throws {
        let pasteboard = NSPasteboard.withUniqueName()
        let monitor = ClipboardMonitor(pasteboard: pasteboard, frontmostApplicationIdentifier: { "com.example.private" })
        defer { monitor.stop(); pasteboard.releaseGlobally() }
        var captures = 0
        monitor.onNewRecord = { _ in captures += 1 }
        monitor.excludedApplicationBundleIdentifiers = ["com.example.private"]
        monitor.start()
        pasteboard.clearContents()
        pasteboard.setString("excluded", forType: .string)
        monitor.excludedApplicationBundleIdentifiers = []
        monitor.checkForChanges()
        try await Task.sleep(for: .milliseconds(30))
        #expect(captures == 0)
    }

    @Test func testPrivacyAndPastePreferencesPersistWithoutDuplicateApplications() {
        let fixture = ModelFixture()
        defer { fixture.cleanUp() }
        let excluded = ExcludedApplication(bundleIdentifier: "com.example.app", name: "Private App")
        fixture.model.excludeApplication(excluded)
        fixture.model.excludeApplication(excluded)
        fixture.model.isCapturePaused = true
        fixture.model.pasteToActiveApplication = false
        #expect(fixture.model.excludedApplications == [excluded])
        #expect(fixture.model.clipboardMonitor.isPaused)
        #expect(fixture.model.clipboardMonitor.excludedApplicationBundleIdentifiers == [excluded.id])
        let monitor = ClipboardMonitor(pasteboard: fixture.pasteboard, frontmostApplicationIdentifier: { nil })
        let reloaded = AppModel(
            defaults: fixture.defaults,
            historyStore: fixture.store,
            clipboardMonitor: monitor,
            directPasteService: DirectPasteService(authorizationCheck: { false }, permissionRequest: {})
        )
        defer { reloaded.stop() }
        #expect(reloaded.excludedApplications == [excluded])
        #expect(reloaded.isCapturePaused)
        #expect(!reloaded.pasteToActiveApplication)
        #expect(monitor.isPaused)
        #expect(monitor.excludedApplicationBundleIdentifiers == [excluded.id])
        reloaded.removeExcludedApplication(excluded)
        #expect(reloaded.excludedApplications.isEmpty)
        #expect(monitor.excludedApplicationBundleIdentifiers.isEmpty)
    }

    @Test func testApplicationPickerRejectsBundleWithoutIdentifier() throws {
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent("\(UUID().uuidString).app")
        defer { try? FileManager.default.removeItem(at: directory) }
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        #expect(ExcludedApplication(url: directory) == nil)
    }
}
